/*
This view is a private one which is used for buttons in Generic dialog, Modal alert and Side panel
For maintaining the button view for the above 3 controls, we are using this
*/
csui.define('smart/dialogs/impl/button/button.view',[
  "nuc/lib/marionette",
  "nuc/lib/underscore",
  'nuc/lib/jquery',
  "smart/behaviors/keyboard.navigation/smart.tabable.region.behavior",
  "hbs!smart/dialogs/impl/button/button",
  "smart/utils/otwc.loader",
  'smart/themes/carbonfiber/ot-icons/icons_smart_action',
], (Marionette, _, $, TabableRegion, btnTemplate) => {
  let ButtonView = Marionette.ItemView.extend({
    template: btnTemplate,

    templateHelpers: function () {
      // for image type buttons do not pass btnText to template.
      let btnText = this.model.get("label") || "";
      return {
        btnText,
      };
    },

    tagName: "otc-button",

    className: function () {
      let _classNames = " " + (this.model?.get("classes") || "");

      // This class is being used by few leading applications to trigger/listen events on this button
      // TODO: need to enhance it further, such that event trigger/listen mechanism to be improve.
      _classNames += this.model?.get("default") ? " cs-add-button" : "";

      // This class is being used to render button left side instead-of right-side.
      // TODO: need to check whoever needs this as it comes under common UX guidelines voilation.
      _classNames += this.model?.get("separate") ? " cs-separate" : "";

      return this._filterBINFBtnClassnames(_classNames);
    },

    attributes: function () {
      let variant = this.model?.get("variant") || "";
      variant = !!variant.length
        ? variant
        : this._getBtnType(this.model || "");
      let attrs = this.model?.attributes || {};
      let defAttrs = { variant };

      if (attrs.id) {
        defAttrs.id = attrs.id;
      }

      if (attrs.disabled !== undefined) {
        defAttrs.disabled = attrs.disabled;
      }

      defAttrs.tabindex = 0;

      let attributes = {
        ...defAttrs,
        ...attrs,
      };
      let updatedAttributes = {
        type: attributes.variant,
        tabindex: attributes.tabindex,
        arialabel: attributes.arialabel
      };
      if (attributes.id) {
        updatedAttributes.id = attributes.id;
      }
      if (!!attributes.disabled || attributes.disabled === "disabled") {
        updatedAttributes.disabled = "disabled";
      }
      if (attrs.toolTip) {
        updatedAttributes.title = attrs.toolTip;
      }

      if (attrs.icon) {
        updatedAttributes.icon = attrs.icon;
        delete updatedAttributes.type;
      }

      if(attrs.attributes?.title){
        updatedAttributes.title = attrs.attributes?.title;
      }

      if(attrs.attributes && attrs.attributes['aria-label']){
        updatedAttributes.arialabel = attrs.attributes['aria-label'];
      }

      return updatedAttributes;
    },

    behaviors: {
      TabableRegion: {
        behaviorClass: TabableRegion,
      },
    },

    triggers: {
      click: "click",
    },

    constructor: function ButtonView(options = {}) {
      // Ensure behaviors are defined
      this.behaviors = this.behaviors || {};
      if (!options.footerTabableRegionBehavior) {
        options.footerTabableRegionBehavior = {
          behaviorClass: TabableRegion,
        };
      }
      // Extend behaviors with footerTabableRegionBehavior
      this.behaviors = _.extend(this.behaviors, {
        TabableRegion: options.footerTabableRegionBehavior,
      });
      this.options = options;
      Marionette.View.prototype.constructor.apply(this, arguments);
      this.listenTo(this, "dom:refresh", _.bind(this.onDomRefresh, this));
      this.listenTo(this.model, 'change', function () {
        this.render();
      });
    },

    /**
     *
     * @returns true if the elements is not disabled and hidden.
     */
    isTabable: function () {
      return this.$el.is(":not(:disabled)") /*&&
        !this?.el
          ?.querySelector("otc-button")
          ?.classList?.contains("binf-hidden")*/;
    },

    onRender: function () {
      let attributes = this.model?.attributes || {};
      this.updateButton(attributes);
    },  
  
     onLastTabElement: function (shiftTab, event) {
      var last = this.$el.parents('.cs-footer-control').find('otc-button').last();
      return last.is(this.$el) && !shiftTab && last.is($(event.target));
     },

    /**
     * @param attributes
     * updateButton - Enables/disables button based on the flag hidden
     */
    updateButton: function (attributes = {}) {
      var _btn = this.el;
      if (attributes.hidden !== undefined) {
        if (attributes.hidden) {
          _btn.classList.add("binf-hidden");
        } else {
          _btn.classList.remove("binf-hidden");
        }
      }
      if (attributes.disabled !== undefined) {
        _btn.setAttribute("disabled", attributes.disabled);
      }
      if (attributes.disabled === false || attributes.disabled === "") {
        _btn.removeAttribute("disabled");
      }
      this.trigger("dom:refresh");
    },

    /**
     *
     * @returns currently focused element
     */
    currentlyFocusedElement: function () {
      this.el && (this.el.attributes.tabindex = 0);
      return this.el;
    },

    onDomRefresh: function () {
      if (this.isTabable()) {
        this.currentlyFocusedElement();
      }
      // Need to unregister tabbable region if not active
      if (!this._isActiveRegion()) {
        this.trigger('tabable:not');
      }
    },

    /**
     * Private method: checks if button view has binf-hidden class or is in disabled state
     * @returns Boolean, true if active else false
     */
    _isActiveRegion: function() {
      if(!this.isRendered || this.el?.classList?.contains('binf-hidden') || this.el?.disabled) {
        return false;
      }
      return true;
    },

    /**
     * Private method: filters the binf button related classnames, otherwise having both
     * otc-button and BINF button styling will cause CSS issues.
     *
     * @param {*} btnClassNames
     * @returns classNames ("filtered classNames as string")
     */
    _filterBINFBtnClassnames: (btnClassNames = "") => {
      var classNames = btnClassNames.split(" ").filter(function (cl) {
        // need to see if any leading application is having class name in the below pattern.
        // binf-btn-<<custom-post-fix>>, for example, binf-btn-custom-primary-button, in this case
        // also, it will be filtered-out, if any impacts ask them to change to some other classname.
        return cl.trim().length && cl.indexOf("binf-btn") === -1;
      });
      classNames = classNames.join(" ");
      return classNames;
    },

    /**
     * Private method: it sets the current button type which is required by OTWC.
     * If there is no option ("variant") is provided, then it tries to obtain the type from the
     * given classnames. For example, if the classnames contains "binf-btn-primary" then button
     * type would be "primary", for "binf-btn-secondary" it would be "secondary" and so on.
     *
     * @param {*} classNames
     * @returns
     */
    _getBtnType: (model = {}) => {
      let classNames = model?.get("classes") || model?.get("className") || "";
      let type = "secondary",
        expectingBtnTypes = ["primary", "secondary"];
      expectingBtnTypes.forEach((expType) => {
        classNames.split(" ").indexOf("binf-btn-" + expType) !== -1 &&
          (type = expType);
      });
      !!model.get("default") && (type = "primary");
      return type === "default" ? "secondary" : type;
    },
  },{
    BTN_TYPE_BACK: 'back',
    BTN_TYPE_NEXT: 'next',
    BTN_TYPE_CANCEL: 'cancel',
    BTN_TYPE_ACTION: 'action'
  });

  return ButtonView;
});


