                'facetId': facetId,
                'topicName': topicName,
                'topicLabel': facetName,
                'clearTitle': lang.clearTitle,
                ariaLabel: _.str.sformat(readOnlyFilter ? lang.facetItemAriaReadOnly :  lang.clearFacetItemAria, topicName, facetName)
